const crypto = require('crypto');
const AWS = require('aws-sdk');

const ALGORITHM = 'aes-256-cbc';
const KEY = Buffer.from(process.env.ENCRYPTION_KEY, 'hex');

function decrypt(encryptedPayload) {
  const parts = encryptedPayload.split(':');
  if (parts.length !== 2) {
    throw new Error('Invalid format');
  }
  const iv = Buffer.from(parts[0], 'base64');
  const ciphertext = Buffer.from(parts[1], 'base64');

  const decipher = crypto.createDecipheriv(ALGORITHM, KEY, iv);
  let decrypted = decipher.update(ciphertext);
  decrypted = Buffer.concat([decrypted, decipher.final()]);
  return decrypted.toString('utf8');
}

function validateSession(token) {
  try {
    const sessionData = decrypt(token);
    const session = JSON.parse(sessionData);
    if (session.exp && Date.now() < session.exp) {
      return { valid: true, user: session.sub, role: session.role };
    }
    return { valid: false, error: 'Session expired' };
  } catch (err) {
    if (err.message.includes('bad decrypt') || 
        err.message.includes('wrong final block length') ||
        err.code === 'ERR_OSSL_EVP_BAD_DECRYPT') {
      return { valid: false, error: 'Invalid padding' };
    }
    if (err instanceof SyntaxError) {
      return { valid: false, error: 'Malformed session data' };
    }
    return { valid: false, error: 'Authentication failed' };
  }
}

exports.handler = async (event) => {
  const headers = event.headers || {};
  const token = headers['x-session-token'] || headers['X-Session-Token'];

  if (!token) {
    return {
      statusCode: 401,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ error: 'No session token provided' })
    };
  }

  const result = validateSession(token);

  if (!result.valid) {
    return {
      statusCode: 403,
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ error: result.error })
    };
  }

  // Fetch user data from DynamoDB
  const dynamodb = new AWS.DynamoDB.DocumentClient();
  const userData = await dynamodb.get({
    TableName: process.env.USERS_TABLE,
    Key: { userId: result.user }
  }).promise();

  return {
    statusCode: 200,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({
      message: `Welcome ${result.user}`,
      role: result.role,
      profile: userData.Item
    })
  };
};
